<?php
declare(strict_types=1);const DB_PATH='/var/lib/hamkare-web/registrations.sqlite3';function reply(array$b,int$s=200):never{http_response_code($s);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($b,JSON_UNESCAPED_UNICODE);exit;}if(($_SERVER['REQUEST_METHOD']??'')!=='GET')reply(['ok'=>false,'error'=>'روش درخواست مجاز نیست.'],405);$code=strtoupper(trim((string)($_GET['code']??'')));$last4=trim((string)($_GET['last4']??''));if(!preg_match('/^[A-Z0-9]{6,12}$/',$code)||!preg_match('/^[0-9]{4}$/',$last4))reply(['ok'=>false,'error'=>'اطلاعات پیگیری معتبر نیست.'],400);try{$db=new PDO('sqlite:'.DB_PATH,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$q=$db->prepare("SELECT name,province,created_at FROM registrations WHERE tracking_code=? AND substr(phone,-4)=? LIMIT 1");$q->execute([$code,$last4]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)reply(['ok'=>false,'error'=>'درخواستی با این مشخصات پیدا نشد.'],404);reply(['ok'=>true,'record'=>$r]);}catch(Throwable$e){error_log('hamkare result failed: '.get_class($e));reply(['ok'=>false,'error'=>'سرویس پیگیری موقتاً در دسترس نیست.'],503);}
